add_filter( 'wp_get_attachment_image_attributes', 'perfectpixel_auto_sizes_attributes', 20 );
add_filter( 'wp_content_img_tag', 'perfectpixel_auto_sizes_content_img', 20 );

function perfectpixel_auto_sizes_needed() {
	return ! function_exists( 'wp_sizes_attribute_includes_valid_auto' ); // WordPress 6.7+ handles it.
}

function perfectpixel_auto_sizes_attributes( $attr ) {
	if ( perfectpixel_auto_sizes_needed() && isset( $attr['loading'], $attr['sizes'] ) && 'lazy' === $attr['loading'] && 0 !== strpos( $attr['sizes'], 'auto' ) ) {
		$attr['sizes'] = 'auto, ' . $attr['sizes'];
	}
	return $attr;
}

function perfectpixel_auto_sizes_content_img( $image ) {
	if ( perfectpixel_auto_sizes_needed() && false !== strpos( $image, 'loading="lazy"' ) && preg_match( '/\ssizes="(?!auto)/', $image ) ) {
		$image = preg_replace( '/\ssizes="/', ' sizes="auto, ', $image, 1 );
	}
	return $image;
}
